-- RentSphere demo dataset (small, realistic, hand-planned).
--
-- Load Schema.sql first, then this file:
--   docker compose exec -T mysql mysql -u"$MYSQL_USER" -p"$MYSQL_PASSWORD" RentSphereSchema < Database/Schema.sql
--   docker compose exec -T mysql mysql -u"$MYSQL_USER" -p"$MYSQL_PASSWORD" RentSphereSchema < Backend/src/main/resources/db/seed-demo.sql
--
-- What it contains: 1 listing owner (ADMIN) and 3 tenants, 9 listings across Cairo,
-- New Cairo, 6th of October, Giza, Alexandria and Riyadh with 11 photos, 9 rental
-- requests (5 accepted, 3 pending, 1 rejected), 5 contracts (4 active, 1 completed), one
-- installment row per contract month, 8 favourites and the notifications the services
-- write for those events.
--
-- Every date is relative to the day the file is loaded, so the data never goes stale:
-- leases are always part-way through, no installment is ever past due, and one is always
-- due in three days so the daily reminder job has something to do.
--
-- It lives on the backend classpath because DemoDataResetService reloads it on a schedule
-- when rentsphere.demo.reset-enabled is true (the public demo, where anyone can sign in
-- to the accounts below).
--
-- Demo logins share the password 'RentSphereDemo2026'; password_hash holds the BCrypt
-- digest the API generated, not the plain text.
--   owner   (ADMIN)  nour.elsayed@nilenest.demo
--   tenants          youssef.farouk@mail.demo, salma.abdelnabi@mail.demo,
--                    mariam.elhosseiny@mail.demo
--
-- For load testing use Database/seed-large-dataset.sql instead (100k listings); it
-- truncates first, so running one after the other is safe.

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE notifications;
TRUNCATE TABLE payments;
TRUNCATE TABLE contracts;
TRUNCATE TABLE rental_requests;
TRUNCATE TABLE favorites;
TRUNCATE TABLE property_images;
TRUNCATE TABLE properties;
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;

SET @today = CURDATE();

