INSERT INTO properties (property_id, owner_id, property_type, title, property_description, price_per_month, city, district, address, latitude, longitude, num_rooms, area_sqm, is_available, created_at, updated_at) VALUES
  (1, 1, 'APARTMENT', 'Sunlit 2-Bedroom Apartment on Degory Street', 'Two bedrooms and a reception on a quiet street in Old Maadi, third floor with lift, a short walk from the Road 9 shops. Furnished, gas and water included.', 650.00, 'Cairo', 'Maadi', '14 Degory Street, Old Maadi', 29.960200, 31.256900, 2, 125.00, 0, TIMESTAMP(@today - INTERVAL 5 MONTH + INTERVAL 2 DAY, '10:15:22'), TIMESTAMP(@today - INTERVAL 5 MONTH + INTERVAL 2 DAY, '10:15:22')),
  (2, 1, 'STUDIO', 'Furnished Studio Steps from the AUC Gate', 'Compact studio in a secured building on 90th Street, fitted kitchenette, balcony, gym and roof access. Utilities metered. Ideal for one person or a couple.', 420.00, 'New Cairo', 'Fifth Settlement', 'Apt 704, Nile Business Park, South 90th Street', 30.019600, 31.499000, 1, 48.00, 1, TIMESTAMP(@today - INTERVAL 5 MONTH + INTERVAL 2 DAY, '10:48:09'), TIMESTAMP(@today - INTERVAL 5 MONTH + INTERVAL 2 DAY, '10:48:09')),
  (3, 1, 'VILLA', 'Family Villa with Private Pool, Palm Hills Extension', 'Detached villa off Wahat Road: four bedrooms, two bathrooms, a landscaped garden and a private pool. Staff quarters, two-car garage, 24-hour compound security.', 1500.00, '6th of October', 'Palm Hills', 'Villa 14, Palm Hills Extension, Wahat Road', 29.966800, 30.943300, 4, 320.00, 0, TIMESTAMP(@today - INTERVAL 5 MONTH + INTERVAL 9 DAY, '16:30:44'), TIMESTAMP(@today - INTERVAL 5 MONTH + INTERVAL 9 DAY, '16:30:44')),
  (4, 1, 'APARTMENT', 'Three Bedrooms with an Unbroken View of the Pyramids', 'Corner apartment on the top floor of a small building in Hadayek El Ahram. West-facing terrace, three bedrooms, two bathrooms, parking in the basement.', 900.00, 'Giza', 'Hadayek El Ahram', 'Apt 12, Gate 1, Hadayek El Ahram', 29.987000, 31.103500, 3, 165.00, 1, TIMESTAMP(@today - INTERVAL 4 MONTH, '12:05:31'), TIMESTAMP(@today - INTERVAL 4 MONTH, '12:05:31')),
  (5, 1, 'APARTMENT', 'Sea-View Apartment on the Alexandria Corniche', 'Reception and two bedrooms facing the Mediterranean in Roushdy, refitted last summer, two balconies, a storage room, and the tram stop one block inland.', 780.00, 'Alexandria', 'Roushdy', '17 El Geish Road, Roushdy', 31.228500, 29.951200, 2, 140.00, 0, TIMESTAMP(@today - INTERVAL 4 MONTH + INTERVAL 6 DAY, '09:52:18'), TIMESTAMP(@today - INTERVAL 4 MONTH + INTERVAL 6 DAY, '09:52:18')),
  (6, 1, 'STUDIO', 'Quiet Studio behind Bibliotheca Alexandrina', 'Single room with kitchenette and bathroom in a restored El Shatby building, four minutes on foot from the library and the corniche. Bills excluded.', 300.00, 'Alexandria', 'El Shatby', '5 Port Said Street, El Shatby', 31.207600, 29.911600, 1, 40.00, 1, TIMESTAMP(@today - INTERVAL 4 MONTH + INTERVAL 6 DAY, '10:20:03'), TIMESTAMP(@today - INTERVAL 4 MONTH + INTERVAL 6 DAY, '10:20:03')),
  (7, 1, 'OFFICE', 'Open-Plan Office Suite in Smart Village', 'Fourth-floor suite with two meeting rooms and a server corner, 210 sqm, raised floor, backup power and two parking badges. Fit-out available on request.', 1200.00, 'Giza', 'Smart Village', 'Building B2, Floor 4, Km 28 Cairo-Alexandria Desert Road', 30.071100, 31.017500, 3, 210.00, 1, TIMESTAMP(@today - INTERVAL 5 MONTH + INTERVAL 10 DAY, '14:11:50'), TIMESTAMP(@today - INTERVAL 5 MONTH + INTERVAL 10 DAY, '14:11:50')),
  (8, 1, 'APARTMENT', 'Furnished Two-Bedroom in Al Malqa, North Riyadh', 'Bright apartment in a gated compound in Al Malqa: master bedroom with en-suite, second bedroom, central AC, residents gym and a shaded childrens play area.', 930.00, 'Riyadh', 'Al Malqa', 'Building 22, Wadi Hajr Street, Al Malqa', 24.803500, 46.613000, 2, 110.00, 1, TIMESTAMP(@today - INTERVAL 3 MONTH, '13:40:27'), TIMESTAMP(@today - INTERVAL 3 MONTH, '13:40:27')),
  (9, 1, 'DUPLEX', 'Modern Duplex with Private Garden in North Katameya', 'Two-storey duplex in a small compound: reception and kitchen on the ground floor, three bedrooms upstairs, a roof terrace, and a fenced garden with an automatic gate.', 1100.00, 'New Cairo', 'Katameya', 'Unit 9, North Katameya Compound', 29.993900, 31.411700, 3, 190.00, 0, TIMESTAMP(@today - INTERVAL 2 MONTH + INTERVAL 3 DAY, '17:22:36'), TIMESTAMP(@today - INTERVAL 2 MONTH + INTERVAL 3 DAY, '17:22:36'));
